 38 static Instruction &findInstructionByName(Function *F, StringRef Name) {
 39   auto *I = findInstructionByNameOrNull(F, Name);
 40   if (I)
 41     return *I;
 42 
 43   llvm_unreachable("Expected value not found");
 44 }
